import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CAKCj7G0.js";const _=JSON.parse('{"title":"谈谈你对vite的理解","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/10.vue3/谈谈vite.md","filePath":"DuOneClass/10.vue3/谈谈vite.md"}'),p={name:"DuOneClass/10.vue3/谈谈vite.md"};function s(r,e,l,n,v,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="谈谈你对vite的理解" tabindex="-1">谈谈你对vite的理解 <a class="header-anchor" href="#谈谈你对vite的理解" aria-label="Permalink to &quot;谈谈你对vite的理解&quot;">​</a></h1><blockquote><p>vite: <a href="https://github.com/vitejs/vite" target="_blank" rel="noreferrer">https://github.com/vitejs/vite</a></p><p>面试题：谈谈你对vite的理解，最好对比webpack说明</p></blockquote><p>webpack 原理图</p><p><img src="https://s2.loli.net/2024/01/14/NBaMPVFvisRuQwH.png" alt="image-20200929144416064"></p><p>vite 原理图</p><p><img src="https://s2.loli.net/2024/01/14/fdETq2nvbPcMUrG.png" alt="image-20200929144957808"></p><blockquote><p>面试题答案：</p><p>webpack会先打包，然后启动开发服务器，请求服务器时直接给予打包结果。 而vite是直接启动开发服务器，请求哪个模块再对该模块进行实时编译。 由于现代浏览器本身就支持ES Module，会自动向依赖的Module发出请求。vite充分利用这一点，将开发环境下的模块文件，就作为浏览器要执行的文件，而不是像webpack那样进行打包合并。 由于vite在启动的时候不需要打包，也就意味着不需要分析模块的依赖、不需要编译，因此启动速度非常快。当浏览器请求某个模块时，再根据需要对模块内容进行编译。这种按需动态编译的方式，极大的缩减了编译时间，项目越复杂、模块越多，vite的优势越明显。 在HMR方面，当改动了一个模块后，仅需让浏览器重新请求该模块即可，不像webpack那样需要把该模块的相关依赖模块全部编译一次，效率更高。 当需要打包到生产环境时，vite使用传统的rollup进行打包，因此，vite的主要优势在开发阶段。另外，由于vite利用的是ES Module，因此在代码中不可以使用CommonJS</p></blockquote>',7)])])}const d=t(p,[["render",s]]);export{_ as __pageData,d as default};
